// MVI — one immutable state, one entry point, a reducer
data class CartState(
  val items: List<CartItem> = emptyList(),
  val isLoading: Boolean = false,
  val error: String? = null
)

sealed interface CartAction {
  data object Load : CartAction
  data class Remove(val id: Long) : CartAction
}

class CartMviViewModel(private val repo: CartRepo) : ViewModel() {
  private val _state = MutableStateFlow(CartState())
  val state = _state.asStateFlow()

  fun onAction(action: CartAction) = when (action) {
    CartAction.Load -> load()
    is CartAction.Remove -> remove(action.id)
  }

  private fun load() = viewModelScope.launch {
    _state.update { it.copy(isLoading = true, error = null) }
    val items = repo.items()
    _state.update { it.copy(isLoading = false, items = items) }
  }
}

// One operation, one call site, no Android imports
class PlaceOrder @Inject constructor(
  private val cart: CartRepository,
  private val orders: OrderRepository,
  private val pricing: PricingRepository
) {
  suspend operator fun invoke(address: Address): Result<OrderId> {
    val items = cart.items()
    if (items.isEmpty()) return Result.failure(EmptyCart)

    val quote = pricing.quote(items, address)          // a rule owned by no single repo
    if (quote.exceedsLimit) return Result.failure(OverLimit(quote.limit))

    return orders.place(items, address, quote).onSuccess { cart.clear() }
  }
}

// A Flow-returning use case is named for observation
class ObserveUnreadCount @Inject constructor(
  private val messages: MessageRepository,
  private val settings: SettingsRepository
) {
  operator fun invoke(): Flow<Int> =
    combine(messages.observeAll(), settings.observeMutedChats()) { all, muted ->
      all.count { !it.isRead && it.chatId !in muted }
    }
}

// At the call site it reads like the action it is
fun submit(address: Address) = viewModelScope.launch {
  _state.update { it.copy(isSubmitting = true) }
  placeOrder(address)
    .onSuccess { _events.send(Event.Placed(it)) }
    .onFailure { _state.update { s -> s.copy(error = it.toUiText()) } }
  _state.update { it.copy(isSubmitting = false) }
}

