// Most screens keep their content while things happen around it
data class FeedUiState(
  val posts: ImmutableList<Post> = persistentListOf(),
  val isRefreshing: Boolean = false,
  val append: AppendState = AppendState.Idle,     // sealed, for the part with real phases
  val banner: UiText? = null
) {
  val isEmpty: Boolean get() = posts.isEmpty() && !isRefreshing   // derived, never stored
}

sealed interface AppendState {
  data object Idle : AppendState
  data object Loading : AppendState
  data class Failed(val message: UiText) : AppendState
}

// Text resolved at the edge, so a locale change is reflected
sealed interface UiText {
  data class Raw(val value: String) : UiText
  data class Res(@StringRes val id: Int, val args: List<Any> = emptyList()) : UiText
}

