class CheckoutViewModel @Inject constructor(
  profiles: ProfileRepository,
  cart: CartRepository,
  flags: FeatureFlags,
  private val placeOrder: PlaceOrder
) : ViewModel() {

  private val submitting = MutableStateFlow(false)

  val state: StateFlow<CheckoutUiState> = combine(
    profiles.observe().orNullOnFailure(),        // one failing source must not kill the state
    cart.observe(),
    flags.observe(Flag.ExpressCheckout),
    submitting
  ) { profile, items, express, isSubmitting ->
    CheckoutUiState(
      profile = profile,
      items = items.toImmutableList(),
      showExpress = express && items.isNotEmpty(),
      isSubmitting = isSubmitting
    )
  }.stateIn(
    scope = viewModelScope,
    started = SharingStarted.WhileSubscribed(5_000),   // survives rotation, stops on leave
    initialValue = CheckoutUiState()
  )
}

