// Step 2: logic leaves the Fragment, the XML stays exactly where it is
class OrdersFragment : Fragment(R.layout.fragment_orders) {
  private val vm: OrdersViewModel by viewModels()

  override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
    val binding = FragmentOrdersBinding.bind(view)
    viewLifecycleOwner.lifecycleScope.launch {
      viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.STARTED) {
        vm.state.collect { state -> binding.render(state) }
      }
    }
  }
}

// Steps 4-5: the same Fragment now hosts Compose — same ViewModel, same navigation
class OrdersComposeFragment : Fragment() {
  private val vm: OrdersViewModel by viewModels()

  override fun onCreateView(
    inflater: LayoutInflater, container: ViewGroup?, saved: Bundle?
  ): View = ComposeView(requireContext()).apply {
    // without this the composition outlives the view and leaks it
    setViewCompositionStrategy(ViewCompositionStrategy.DisposeOnViewLifecycleDestroyed)
    setContent {
      AppTheme {
        val state by vm.state.collectAsStateWithLifecycle()
        OrdersScreen(
          state = state,
          onOpen = { id -> findNavController().navigate(OrdersDirections.toDetail(id)) }
        )
      }
    }
  }
}

